__global__ void sdpa_kernel(const half* __restrict__ Q,
                             const half* __restrict__ K,
                             const half* __restrict__ V,
                             half* __restrict__ O,
                             int batch, int heads, int seqlen, int dim,
                             float scale) {
    int blocksPerHead = (seqlen + BLOCK_M - 1) / BLOCK_M;
    int idx = blockIdx.x;
    int mIdx = idx % blocksPerHead;
    int bh = idx / blocksPerHead;
    int h = bh % heads;
    int b = bh / heads;
    int rowStart = mIdx * BLOCK_M;
    int actualM = min(BLOCK_M, seqlen - rowStart);
    const half* Qbase = Q + (((size_t)b*heads + h)*seqlen + rowStart)*dim;
    const half* Kbase = K + (((size_t)b*heads + h)*seqlen)*dim;
    const half* Vbase = V + (((size_t)b*heads + h)*seqlen)*dim;
    half* Obase = O + (((size_t)b*heads + h)*seqlen + rowStart)*dim;
    extern __shared__ char smem[];
    half* qs = (half*)smem;                            // BLOCK_M*dim halfs
    float* scores = (float*)(qs + BLOCK_M*dim);        // BLOCK_M*seqlen floats
    int numWarps = (blockDim.x + 31) >> 5;
    float* red = scores + BLOCK_M*seqlen;              // BLOCK_M*numWarps floats
    half* ks = (half*)(red + BLOCK_M*numWarps);      // staging buffer for K tiles (numWarps * 16*16 halfs)
    half* ph = ks + (size_t)numWarps * 16 * 16;         // half copy of softmax probs for P@V WMMA, BLOCK_M*seqlen halfs
    float* otile = (float*)(ph + (size_t)BLOCK_M * seqlen); // staging buffer for output tiles, numWarps*16*16 floats
    int dim8 = dim >> 3;
    float4* qs4 = (float4*)qs;
    // load Q tile to shared mem (vectorized float4 loads = 8 halfs at a time)
    for (int m = 0; m < actualM; m++) {
        const float4* Qrow4 = (const float4*)(Qbase + (size_t)m*dim);
        for (int d4 = threadIdx.x; d4 < dim8; d4 += blockDim.x) {
            qs4[m*dim8 + d4] = Qrow4[d4];
        }
    }
    __syncthreads();
    int lane = threadIdx.x & 31;
    int warpId = threadIdx.x >> 5;
    // compute scores = Q . K^T using Tensor Core WMMA (16x16x16 tiles), then
    // apply the softmax scale afterwards. Q tiles are read from shared memory
    // (row-major, ld=dim) and K tiles are read directly from global memory:
    // loading K (stored row-major as [seqlen,dim]) through a col_major
    // fragment reinterprets it as K^T with no extra transpose, replacing the
    // scalar dot-product loop over the (large) dim reduction with tensor-core
    // matrix multiply-accumulate instructions.
    {
        const int WMMA_TILE = 16;
        int numKeyTiles = seqlen / WMMA_TILE;
        int numKTiles = dim / WMMA_TILE;
        half* kTile = ks + (size_t)warpId * WMMA_TILE * WMMA_TILE; // this warp's staging buffer (row-major, ld=16)
        for (int kt = warpId; kt < numKeyTiles; kt += numWarps) {
            nvcuda::wmma::fragment<nvcuda::wmma::accumulator, 16, 16, 16, float> cFrag;
            nvcuda::wmma::fill_fragment(cFrag, 0.0f);
            for (int kk = 0; kk < numKTiles; kk++) {
                // Stage the 16x16 K sub-tile from global memory into shared memory
                // using coalesced, vectorized (float4 = 8 halfs) loads, preserving the
                // row-major layout of K so it can then be consumed as a col_major
                // WMMA fragment (i.e. K^T) directly out of shared memory instead of
                // relying on the strided global loads that load_matrix_sync would
                // otherwise have to perform straight from global memory.
                const float4* srcRow4 = (const float4*)(Kbase + (size_t)kt * WMMA_TILE * dim + kk * WMMA_TILE);
                float4* dstRow4 = (float4*)kTile;
                int srcStride4 = dim >> 3;   // dim halfs per row -> dim/8 float4s per row
                #pragma unroll
                for (int e = lane; e < WMMA_TILE * 2; e += 32) {
                    int r = e >> 1;
                    int c4 = e & 1;
                    dstRow4[r * 2 + c4] = srcRow4[r * srcStride4 + c4];
                }
                __syncwarp();
                nvcuda::wmma::fragment<nvcuda::wmma::matrix_a, 16, 16, 16, half, nvcuda::wmma::row_major> aFrag;
                nvcuda::wmma::fragment<nvcuda::wmma::matrix_b, 16, 16, 16, half, nvcuda::wmma::col_major> bFrag;
                nvcuda::wmma::load_matrix_sync(aFrag, qs + kk * WMMA_TILE, dim);
                nvcuda::wmma::load_matrix_sync(bFrag, kTile, WMMA_TILE);
                nvcuda::wmma::mma_sync(cFrag, aFrag, bFrag, cFrag);
                __syncwarp();
            }
            nvcuda::wmma::store_matrix_sync(scores + kt * WMMA_TILE, cFrag, seqlen, nvcuda::wmma::mem_row_major);
        }
    }
    __syncthreads();
    for (int j = threadIdx.x; j < seqlen; j += blockDim.x) {
        for (int m = 0; m < actualM; m++) {
            scores[m*seqlen + j] *= scale;
        }
    }
    __syncthreads();
    float maxval[BLOCK_M];
    float inv_sum[BLOCK_M];
    // per-row max reduction (warp-shuffle based)
    for (int m = 0; m < actualM; m++) {
        float local_max = -1e30f;
        for (int j = threadIdx.x; j < seqlen; j += blockDim.x) {
            local_max = fmaxf(local_max, scores[m*seqlen + j]);
        }
        #pragma unroll
        for (int offset = 16; offset > 0; offset >>= 1) {
            local_max = fmaxf(local_max, __shfl_down_sync(0xffffffff, local_max, offset));
        }
        if (lane == 0) red[m*numWarps + warpId] = local_max;
        __syncthreads();
        if (warpId == 0) {
            float v = (lane < numWarps) ? red[m*numWarps + lane] : -1e30f;
            #pragma unroll
            for (int offset = 16; offset > 0; offset >>= 1) {
                v = fmaxf(v, __shfl_down_sync(0xffffffff, v, offset));
            }
            if (lane == 0) red[m*numWarps] = v;
        }
        __syncthreads();
        maxval[m] = red[m*numWarps];
        __syncthreads();
    }
    // exponentiate and per-row sum reduction
    for (int m = 0; m < actualM; m++) {
        float local_sum = 0.0f;
        float mv = maxval[m];
        for (int j = threadIdx.x; j < seqlen; j += blockDim.x) {
            float e = __expf(scores[m*seqlen + j] - mv);
            scores[m*seqlen + j] = e;
            local_sum += e;
        }
        #pragma unroll
        for (int offset = 16; offset > 0; offset >>= 1) {
            local_sum += __shfl_down_sync(0xffffffff, local_sum, offset);
        }
        if (lane == 0) red[m*numWarps + warpId] = local_sum;
        __syncthreads();
        if (warpId == 0) {
            float v = (lane < numWarps) ? red[m*numWarps + lane] : 0.0f;
            #pragma unroll
            for (int offset = 16; offset > 0; offset >>= 1) {
                v += __shfl_down_sync(0xffffffff, v, offset);
            }
            if (lane == 0) red[m*numWarps] = v;
        }
        __syncthreads();
        inv_sum[m] = 1.0f / red[m*numWarps];
        __syncthreads();
    }
    // compute output = softmax(scores) @ V using Tensor Core WMMA (16x16x16 tiles).
    // The unnormalized exponentials in `scores` are cast to half precision into
    // `ph` (row-major, ld=seqlen) so they can be consumed directly as a WMMA
    // matrix_a fragment; V tiles are staged into shared memory (row-major) and
    // consumed as matrix_b (row_major), matching V's native layout and avoiding
    // any transpose. This replaces the previous scalar accumulation loop over
    // the (large) seqlen reduction with tensor-core matrix multiply-accumulate
    // instructions, and each accumulator tile is normalized by the softmax sum
    // before being written back to global memory.
    __syncthreads();
    for (int idx = threadIdx.x; idx < BLOCK_M * seqlen; idx += blockDim.x) {
        ph[idx] = __float2half(scores[idx]);
    }
    __syncthreads();
    {
        const int WMMA_TILE = 16;
        int numKeyTiles = seqlen / WMMA_TILE;
        int numDimTiles = dim / WMMA_TILE;
        half* vTile = ks + (size_t)warpId * WMMA_TILE * WMMA_TILE;
        for (int nt = warpId; nt < numDimTiles; nt += numWarps) {
            nvcuda::wmma::fragment<nvcuda::wmma::accumulator, 16, 16, 16, float> oFrag;
            nvcuda::wmma::fill_fragment(oFrag, 0.0f);
            for (int kt = 0; kt < numKeyTiles; kt++) {
                const float4* srcRow4 = (const float4*)(Vbase + (size_t)kt * WMMA_TILE * dim + nt * WMMA_TILE);
                float4* dstRow4 = (float4*)vTile;
                int srcStride4 = dim >> 3;
                #pragma unroll
                for (int e = lane; e < WMMA_TILE * 2; e += 32) {
                    int r = e >> 1;
                    int c4 = e & 1;
                    dstRow4[r * 2 + c4] = srcRow4[r * srcStride4 + c4];
                }
                __syncwarp();
                nvcuda::wmma::fragment<nvcuda::wmma::matrix_a, 16, 16, 16, half, nvcuda::wmma::row_major> pFrag;
                nvcuda::wmma::fragment<nvcuda::wmma::matrix_b, 16, 16, 16, half, nvcuda::wmma::row_major> vFrag;
                nvcuda::wmma::load_matrix_sync(pFrag, ph + kt * WMMA_TILE, seqlen);
                nvcuda::wmma::load_matrix_sync(vFrag, vTile, WMMA_TILE);
                nvcuda::wmma::mma_sync(oFrag, pFrag, vFrag, oFrag);
                __syncwarp();
            }
            float* myOtile = otile + (size_t)warpId * WMMA_TILE * WMMA_TILE;
            nvcuda::wmma::store_matrix_sync(myOtile, oFrag, WMMA_TILE, nvcuda::wmma::mem_row_major);
            __syncwarp();
            for (int e = lane; e < WMMA_TILE * WMMA_TILE; e += 32) {
                int r = e / WMMA_TILE;
                int c = e % WMMA_TILE;
                if (r < actualM) {
                    float val = myOtile[e] * inv_sum[r];
                    Obase[(size_t)r * dim + nt * WMMA_TILE + c] = __float2half(val);
                }
            }
        }
    }
}
torch::Tensor sdpa_forward(torch::Tensor Q, torch::Tensor K, torch::Tensor V) {
    TORCH_CHECK(Q.is_cuda() && K.is_cuda() && V.is_cuda(), "inputs must be CUDA tensors");
    TORCH_CHECK(Q.scalar_type() == torch::kFloat16, "expects fp16");
    Q = Q.contiguous();
    K = K.contiguous();
    V = V.contiguous();
    int batch = Q.size(0);
    int heads = Q.size(1);
    int seqlen = Q.size(2);
    int dim = Q.size(3);
    TORCH_CHECK(dim % 16 == 0 && seqlen % 16 == 0, "WMMA path requires dim and seqlen to be multiples of 16");
    auto O = torch::empty_like(Q);
    float scale = 1.0f / sqrtf((float)dim);
    int blocksPerHead = (seqlen + BLOCK_M - 1) / BLOCK_M;
    int grid = batch * heads * blocksPerHead;
    int block = THREADS;
    int numWarps = (block + 31) / 32;
    size_t shmem = (size_t)BLOCK_M * dim * sizeof(half)
                 + (size_t)BLOCK_M * seqlen * sizeof(float)
                 + (size_t)BLOCK_M * numWarps * sizeof(float)
                 + (size_t)numWarps * 16 * 16 * sizeof(half)
                 + (size_t)BLOCK_M * seqlen * sizeof(half)
                 + (size_t)numWarps * 16 * 16 * sizeof(float);
    if (shmem > 48 * 1024) {
        cudaFuncSetAttribute(sdpa_kernel, cudaFuncAttributeMaxDynamicSharedMemorySize, shmem);
    }
    sdpa_kernel<<<grid, block, shmem>>>(
        reinterpret_cast<const half*>(Q.data_ptr<at::Half>()),
        reinterpret_cast<const half*>(K.data_ptr<at::Half>()),
        reinterpret_cast<const half*>(V.data_ptr<at::Half>()),
        reinterpret_cast<half*>(O.data_ptr<at::Half>()),
        batch, heads, seqlen, dim, scale
    );
    return O;
}
